import tensorflow as tf

@tf.function
def f(x):
    print("tracing with shape", x.shape)   # Python side effect: tracing only
    tf.print("running")                     # graph op: every call
    return x * 2

f(tf.constant([1.0, 2.0]))          # tracing with shape (2,)  /  running
f(tf.constant([3.0, 4.0]))          # running  (same signature, graph reused)
f(tf.constant([1.0, 2.0, 3.0]))     # traces again for the new shape, then running
print(f.experimental_get_tracing_count())   # 2

@tf.function(input_signature=[tf.TensorSpec([None], tf.float32)])
def total(x):
    return tf.reduce_sum(x)

print(total(tf.constant([1.0, 2.0])).numpy())        # 3.0
print(total(tf.constant([1.0, 2.0, 3.0])).numpy())   # 6.0, no retrace
